      "book": "Mark",
      "chapter": 1,
      "verse": 2,
      "startVerse": 2,
      "endVerse": 3,
      "author": "Tried By Fire",
      "authorHandle": "@TriedByFire",
      "text": "Verse three is specifically referenced from Isaiah:",
      "likes": 0,
